def to_base(n, b):
    if n == 0:
        return '0'
    digs = '0123456789ABCDEF'
    out = ''
    while n:
        out = digs[n % b] + out
        n //= b
    return out
print(to_base(47, 16))  # '2F'

def as_signed(bits, n):
    if bits & (1 << (n-1)):
        return bits - (1 << n)
    return bits
print(as_signed(0b11111111, 8))  # -1

def neg(x, n):
    return (~x + 1) & ((1 << n) - 1)
print(neg(5, 8))  # 251 = -5 pattern

def ones_comp_neg(x, n):
    return (~x) & ((1 << n) - 1)
print(bin(ones_comp_neg(5, 8)))  # 0b11111010

