def close(a, b, rel=1e-9, absol=1e-12):
    return abs(a - b) <= max(rel * max(abs(a), abs(b)), absol)

def add_checked(a, b, bits=32):
    lo, hi = -(1 << (bits-1)), (1 << (bits-1)) - 1
    r = a + b
    if not (lo <= r <= hi):
        raise OverflowError('signed overflow')
    return r

