def decode(bits, code):
    inv = {v:k for k,v in code.items()}
    out, buf = [], ''
    for b in bits:
        buf += b
        if buf in inv:
            out.append(inv[buf]); buf = ''
    return ''.join(out)
print(decode('010110111', code))  # a b c d

def crc8(data, poly=0x07):
    crc = 0
    for byte in data:
        crc ^= byte
        for _ in range(8):
            crc = ((crc << 1) ^ poly) & 0xFF if crc & 0x80 else (crc << 1) & 0xFF
    return crc

def hamming(a, b):
    return bin(a ^ b).count('1')
